					DatabaseMetadata: events.DatabaseMetadata{
						DatabaseUser: "sa",
					},
					Metadata: events.Metadata{
						Type: libevents.DatabaseSessionSQLServerRPCRequestEvent,
						Code: libevents.SQLServerRPCRequestCode,
					},
					Parameters: []string{"select @@version"},
