// Error represents an SQL Server error. This
// type includes methods for reading the contents
// of the struct, which allows calling programs
// to check for specific error conditions without
// having to import this package directly.
type Error struct {
	Number     int32
	State      uint8
	Class      uint8
	Message    string
	ServerName string
	ProcName   string
	LineNo     int32
	// All lists all errors that were received from first to last.
	// This includes the last one, which is described in the other members.
	All []Error
}

// Marshal marshals the error to the wire protocol token.
func (e *Error) Marshal() ([]byte, error) {
	buf := bytes.NewBuffer([]byte{
		byte(tokenError),
	})
	length := 2 + // length
		4 + // number
		1 + // state
		1 + // class
		(2 + 2*len(e.Message)) + // message
		(1 + 2*len(e.ServerName)) + // server name
		(1 + 2*len(e.ProcName)) + // proc name
		4 // line no
	if err := binary.Write(buf, binary.LittleEndian, uint16(length)); err != nil {
		return nil, err
	}
	if err := binary.Write(buf, binary.LittleEndian, e.Number); err != nil {
		return nil, err
	}
	if err := buf.WriteByte(e.State); err != nil {
		return nil, err
	}
	if err := buf.WriteByte(e.Class); err != nil {
		return nil, err
	}
	if err := writeUsVarChar(buf, e.Message); err != nil {
		return nil, err
	}
	if err := writeBVarChar(buf, e.ServerName); err != nil {
		return nil, err
	}
	if err := writeBVarChar(buf, e.ProcName); err != nil {
		return nil, err
	}
	if err := binary.Write(buf, binary.LittleEndian, e.LineNo); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func (e Error) Error() string {
	return "mssql: " + e.Message
}

func (e Error) String() string {
	return e.Message
}

// SQLErrorNumber returns the SQL Server error number.
func (e Error) SQLErrorNumber() int32 {
	return e.Number
}

func (e Error) SQLErrorState() uint8 {
	return e.State
}

func (e Error) SQLErrorClass() uint8 {

